(o/'scrollviewport.html').write_text('''<!doctype html><meta charset="utf-8"><title>ScrollViewport · original isolation</title><link rel="stylesheet" href="sidebar-original.css"><style>body{min-width:1000px;min-height:700px}#scroll-target{position:absolute;left:30px;top:60px;width:220px;height:400px}#scroll-content{height:1140px;flex-shrink:0;background:repeating-linear-gradient(to bottom,#343640 0 39px,#41434a 39px 40px,#2b2d31 40px 79px,#41434a 79px 80px)}#controls{position:absolute;left:300px;top:60px;display:grid;gap:12px}#controls button{min-height:44px;width:180px}#out{position:absolute;left:300px;top:380px}</style><aside class="rail" id="scroll-target" aria-label="Original scroll fixture"><div id="scroll-content"></div></aside><div id="controls"><button id="scroll-record">Record scroll state</button><button id="scroll-reset">Reset to top</button><button id="scroll-bottom">Go to bottom</button><button id="scroll-short">No overflow</button><button id="scroll-long">Restore overflow</button><button id="scroll-layouts">Record layouts</button><button id="scroll-tall">Tall page test</button><button id="scroll-boundaries">Record boundaries</button><button id="scroll-focus-child">Focus child test</button><button id="scroll-detach">Detach viewport</button><button id="scroll-minimum">Record minimum sizes</button></div><output id="out">Ready</output><script>const pane=document.getElementById('scroll-target'),content=document.getElementById('scroll-content'),out=document.getElementById('out');let wheels=[],frames=[],inputs=[],activeUntil=0;function sample(t){if(t<activeUntil){frames.push({time:t,offset:pane.scrollTop});requestAnimationFrame(sample)}}pane.addEventListener('scroll',e=>{let t=performance.now();if(t>=activeUntil)requestAnimationFrame(sample);activeUntil=t+800},{passive:true});pane.addEventListener('focusin',e=>inputs.push({kind:'focus',time:performance.now(),target:e.target.id,focusVisible:e.target.matches(':focus-visible')}));pane.addEventListener('focusout',e=>inputs.push({kind:'blur',time:performance.now(),target:e.target.id}));pane.addEventListener('pointerup',e=>{inputs.push({kind:'released',time:performance.now(),trusted:e.isTrusted})},{passive:true});pane.addEventListener('pointerdown',e=>{inputs.push({kind:'pressed',time:performance.now(),trusted:e.isTrusted});activeUntil=performance.now()+2000;requestAnimationFrame(sample)},{passive:true});pane.addEventListener('keydown',e=>{inputs.push({kind:'key',key:e.key,time:performance.now(),trusted:e.isTrusted});activeUntil=performance.now()+800;requestAnimationFrame(sample)},{passive:true});pane.addEventListener('wheel',e=>{wheels.push({time:performance.now(),deltaX:e.deltaX,deltaY:e.deltaY,deltaMode:e.deltaMode,trusted:e.isTrusted});activeUntil=performance.now()+800;requestAnimationFrame(sample)},{passive:true});function read(){let r=pane.getBoundingClientRect(),b=content.getBoundingClientRect();return{width:r.width,height:r.height,clientWidth:pane.clientWidth,clientHeight:pane.clientHeight,scrollWidth:pane.scrollWidth,scrollHeight:pane.scrollHeight,offset:pane.scrollTop,content:{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height},wheels,frames,inputs,focused:document.activeElement===pane,focusVisible:pane.matches(':focus-visible'),active:document.activeElement.id}}async function post(value){let response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,...value})});if(!response.ok)throw Error('Evidence failed');out.textContent='Scroll state recorded'}document.getElementById('scroll-minimum').onclick=async()=>{let rows=[];content.style.height='1140px';for(const requestedHeight of [60,36,20,0]){pane.style.height=requestedHeight+'px';pane.scrollTop=0;rows.push({requestedHeight,...read()})}await post({rows});pane.style.height='400px';pane.scrollTop=0};document.getElementById('scroll-detach').onclick=()=>{pane.remove();setTimeout(()=>document.body.append(pane),200);out.textContent='Detach pending'};document.getElementById('scroll-focus-child').onclick=()=>{pane.style.height='400px';content.style.height='1140px';content.style.position='relative';pane.scrollTop=0;document.getElementById('scroll-child')?.remove();const child=document.createElement('button');child.id='scroll-child';child.textContent='Focus child';child.style.cssText='position:absolute;top:60px;left:0;width:100px;height:30px';content.append(child);out.textContent='Focus child test'};document.getElementById('scroll-boundaries').onclick=async()=>{let rows=[];const take=id=>rows.push({id,...read()});pane.style.height='400px';content.style.height='1140px';pane.scrollTop=500;take('offset500');content.style.height='200px';take('shrink');content.style.height='1140px';take('grow');pane.scrollTop=1e9;take('bottom400');pane.style.height='660px';take('resize660');pane.style.height='960px';take('resize960');content.style.height='200px';take('short960');content.style.height='1140px';take('grow960');pane.scrollTop=NaN;take('nan');pane.scrollTop=Infinity;take('infinity');pane.scrollTop=-Infinity;take('negative-infinity');pane.style.height='400px';content.style.height='1140.375px';pane.scrollTop=1e9;take('fractional-bottom');content.style.height='1140px';take('rounded-shrink');pane.scrollTop=0;content.style.position='relative';const target=document.createElement('button');target.textContent='Focus target';target.style.cssText='position:absolute;top:1000px;left:0;width:80px;height:30px';content.append(target);target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});take('bring-nearest');target.remove();await post({rows});pane.style.height='400px';content.style.height='1140px';pane.scrollTop=0};document.getElementById('scroll-tall').onclick=()=>{pane.style.height='660px';content.style.height='3000px';pane.scrollTop=0;wheels=[];frames=[];inputs=[];out.textContent='Tall page test'};document.getElementById('scroll-record').onclick=()=>post(read());document.getElementById('scroll-reset').onclick=()=>{document.getElementById('scroll-child')?.remove();pane.scrollTop=0;wheels=[];frames=[];inputs=[];out.textContent='Top'};document.getElementById('scroll-bottom').onclick=()=>{pane.scrollTop=1e9;out.textContent='Bottom'};document.getElementById('scroll-short').onclick=()=>{content.style.height='200px';out.textContent='No overflow'};document.getElementById('scroll-long').onclick=()=>{content.style.height='1140px';out.textContent='Overflow'};document.getElementById('scroll-layouts').onclick=async()=>{let rows=[];for(const height of[400,660,960])for(const extent of[200,1140])for(const offset of[0,123.456,1e9]){pane.style.height=height+'px';content.style.height=extent+'px';pane.scrollTop=offset;rows.push({requested:offset,...read()})}await post({rows});pane.style.height='400px';content.style.height='1140px';pane.scrollTop=0};</script>''');print('Original UA scroll fixture prepared')
